import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  for (final scale in [1.0, 1.5]) {
    testWidgets('proxy follows pointer at scale $scale', (tester) async {
      await tester.pumpWidget(MaterialApp(
        builder: (context, child) => Transform.scale(
            scale: scale, alignment: Alignment.topLeft, child: child),
        home: Scaffold(
          body: SizedBox(
            height: 50,
            child: ReorderableListView(
              scrollDirection: Axis.horizontal,
              buildDefaultDragHandles: false,
              onReorder: (_, __) {},
              children: [
                for (final (i, label) in ['A', 'B', 'C'].indexed)
                  ReorderableDragStartListener(
                    key: ValueKey(label),
                    index: i,
                    child: SizedBox(width: 100, child: Center(child: Text(label))),
                  ),
              ],
            ),
          ),
        ),
      ));
      final start = tester.getCenter(find.text('C'));
      final gesture = await tester.startGesture(start);
      await tester.pump();
      await gesture.moveBy(const Offset(-60, 0));
      await tester.pump();
      final pointer = start - const Offset(60, 0);
      // Passes at 1.0; at 1.5 the proxy is at 472.5 while the pointer is at 315.
      expect(tester.getCenter(find.text('C').last).dx,
          moreOrLessEquals(pointer.dx, epsilon: 1));
      await gesture.up();
      await tester.pumpAndSettle();
    });
  }
}
